    static let healthy: SpeakerReport = decode(healthyJSON)

    /// Three runs that could not be used: nothing is concluded.
    static let inconclusive: SpeakerReport = decode(inconclusiveJSON)

    /// The finding the Finding screen shows.
    static var buzz: Finding { buzzing.findings.first { $0.kind == .distortion }! }

    private static func decode(_ json: String) -> SpeakerReport {
        do {
            return try JSONDecoder().decode(SpeakerReport.self, from: Data(json.utf8))
        } catch {
            fatalError("A debug fixture no longer decodes as a SpeakerReport: \(error)")
        }
    }

